-- ============================================================
-- CampusNOVA — Importación de datos (PARTE 2: responsables + asignaciones)
-- Ejecutar DESPUÉS de 01_datos_core.sql
--
-- El export de Medo NO incluyó los usuarios/perfiles. La tabla
-- asignaciones_espacios.responsable_id tiene FK obligatoria a profiles(id).
-- Este script crea 30 perfiles TEMPORALES con los UUID originales para no
-- perder las 237 asignaciones. Quedan inactivos (activo=false) y con nombre
-- 'Responsable pendiente'. Luego edítalos en Panel > Usuarios con el nombre
-- y correo real (ver RECONCILIACION_RESPONSABLES.md para saber quién es cada uno).
-- ============================================================

-- 1) Crear usuarios auth (placeholder) con los UUID originales.
--    Sin contraseña utilizable; se reactivan con invitación/Google real.
DO $$
DECLARE
  ids uuid[] := ARRAY[
    'dabb9c60-5705-4f2d-8c10-ef5f27b6fbeb',
    'a493222f-c376-443b-b18b-f87e21eab713',
    'd03e10fc-4a1b-470d-bd33-b4189a59ca19',
    '707a9372-2ad6-43e1-a8c6-150a84ee7843',
    '9c715c48-bbc0-407b-8197-302d5ff63d32',
    '77c2b0fe-05a9-4242-b8ef-357aae7ff13f',
    '42034c7e-bad6-4160-98ca-96466c1b0eff',
    'a1dad22a-55bd-4af8-a52d-81b1dfeafdeb',
    '92f9d89d-f4b9-4249-8bae-00da828a1f72',
    'dbb283b9-e8ed-41d0-9a9a-e1293e2cf83f',
    '794f027f-13e8-4ac8-a948-267be726b5f0',
    '22af3d84-4189-4b1c-97d5-a2757fcf468a',
    '8ca8557c-0fb8-4109-993a-8a58862c8f3e',
    '6e1d3b28-1c68-4e63-a60f-e9325fb542c6',
    'b55da4c8-982b-4b01-ab6a-4a7a9d96f487',
    '1bd3b0f3-aebb-4393-a6f3-9141cdefb488',
    '5c77e900-867e-4bfb-992f-493b73fa0bb5',
    '607a3c9e-4058-4971-9147-72f80d3cecc7',
    '37a7a166-668d-4ce0-a2d8-8466fd1a705b',
    'dc5e5341-e20d-4fc8-899c-6cd2df9022b9',
    'e6842eba-9c9e-47f2-a7c6-f68f63aa5a64',
    '658a69f4-7774-48e7-9226-ac91321ef7d2',
    'b5de35f0-3070-40de-9347-b94c17c915df',
    '4096e0d2-9a67-4d67-ad4b-ec7c2f863e66',
    '172ebb20-9a3c-49db-9561-2a6643d1318c',
    '244f8fc8-e0a3-4440-94b7-713ff95ea4cf',
    'c34b2f53-a31e-47af-a8fe-70076923f167',
    '2e17883a-be3a-4250-8b0f-31d781c76e80',
    '6bcdc316-b76d-4b00-ad56-d5c965d44ad9',
    '8fb156ff-3a97-49cd-931d-3e5f594e5775'
  ];
  uid uuid;
  n int;
BEGIN
  FOREACH uid IN ARRAY ids LOOP
    n := array_position(ids, uid);
    -- Crear en auth.users solo si no existe
    IF NOT EXISTS (SELECT 1 FROM auth.users WHERE id = uid) THEN
        instance_id, id, aud, role, email,
        encrypted_password, email_confirmed_at, created_at, updated_at,
        raw_app_meta_data, raw_user_meta_data, is_super_admin
      ) VALUES (
        '00000000-0000-0000-0000-000000000000', uid, 'authenticated', 'authenticated',
        'responsable-pendiente-' || n || '@cotecnova.edu.co',
        NULL, NULL, now(), now(),
        '{"provider":"email","providers":["email"]}'::jsonb, '{}'::jsonb, false
      );
    END IF;
    -- Crear/ajustar el perfil (la tabla profiles puede tener trigger que ya lo creó)
    VALUES (uid, 'responsable-pendiente-' || n || '@cotecnova.edu.co',
            'Responsable pendiente ' || n, 'responsable', false)
    ON CONFLICT (id) DO UPDATE
      SET role = 'responsable',
          activo = false,
          nombre = COALESCE(public.profiles.nombre, EXCLUDED.nombre);
  END LOOP;
END $$;

-- 2) Importar las asignaciones (ahora las FK existen).

